from dsl import *
FIN = "General information, not financial, tax or legal advice; rules, thresholds and entitlements differ by country and change — confirm with official sources or a regulated adviser before acting."
IMM = "General information, not financial, tax, legal or immigration advice; rules differ by country and by your status and change often — check official sources, a registered adviser or a recognised migrant-support charity."
SEP = "General information, not legal or financial advice; separation and tenancy rules differ by country and by whether you are married — speak to a solicitor, mediator or free advice service before signing or paying anything."

# ---------------------------------------------------------------- students
APP("term_purse", "Term Purse", "Make the loan drop last until the next one", "Finance", ["#3949AB", "#FFB300", "#26A69A"], "hat",
 "Term Purse turns each student loan or grant instalment into a weekly allowance that survives the whole term, plans around rent day and exam weeks, and finds the part-time hours that pay without wrecking your grades.",
 "You are a straight-talking student money mentor: you know rent eats the loan first, you never lecture about coffee, and you plan in weeks not months.",
 "Stretch the drop", "Tell us when money lands and what rent costs; we do the weekly maths.", ["Weekly allowance from each instalment", "Rent-day and exam-week planning", "Part-time hours that fit your timetable"],
 [NAME, CH("year", "Year of study", ["First", "Second", "Third+", "Postgrad"]), NUM("rent", "Monthly rent incl. bills", "550"), TXT("currency", "Currency", "GBP")],
 [T("stretch", "Stretch this instalment", "Lump sum → weekly allowance", "📆", [NUM("amount", "Instalment received", "2900"), NUM("weeks", "Weeks until the next one", "15"), TXT("fixed", "Fixed costs this term", "phone 15/mo, gym 20/mo, society fees 30")],
    "Instalment {amount} must last {weeks} weeks with the profile's monthly rent and these fixed costs: {fixed}. Sections: kv (total fixed for the period, safe-to-spend total, weekly allowance, a 'panic line' balance you must not go under before the next drop); table (Week | Opening balance | Rent/fixed due | Allowance | Closing balance) with one row per week; a callout on the two weeks most likely to blow the plan (arrival/freshers week, exam week, birthdays) and how much to hold back for them; bullets of 3 ways to cut the weekly figure if the allowance is under what you can live on.", "kv, table, callout, bullets", "Do the maths", "Stretching…"),
  T("hours", "Part-time hours math", "How many shifts you actually need", "🕒", [NUM("gap", "Monthly shortfall to cover", "180"), NUM("wage", "Hourly wage after tax", "10.5"), CH("load", "Course load", ["Light", "Normal", "Heavy (labs/placement)"], "Normal")],
    "Shortfall {gap} per month at {wage} per hour with a {load} course load. Sections: kv (hours per month needed, hours per week, shifts per week at 4-hour shifts, a maximum safe weekly cap for this course load); cards for 4 student-friendly job types (meta = typical hourly · flexibility · exam-season friendliness); a callout on the weekly hours where grades typically start to slide and how to raise exam weeks with a manager; a quote with a message asking for reduced hours during exams.", "kv, cards, callout, quote", "Count the hours", "Counting shifts…"),
  T("kit", "Course kit on a budget", "Textbooks, software, equipment", "📚", [LONG("list", "Reading list / kit list", "Organic Chemistry 9th ed, lab coat, graphics calculator, Adobe CC…"), NUM("budget", "Kit budget", "120")],
    "Kit list: {list}. Budget: {budget}. Sections: table (Item | Buy new | Used / older edition | Borrow / library / free alternative | Recommended route | Est. cost); a checklist of where to look, in order (library reserve, department loan, student-union sales, older editions, student software licences); a callout on the items you genuinely should not skimp on; kv (total at the recommended route vs budget, saving vs buying everything new).", "table, checklist, callout, kv", "Cut the kit cost", "Hunting bargains…"),
  T("emergency", "Money ran out", "Get to the next drop safely", "🆘", [NUM("left", "Money left", "40"), NUM("days", "Days until next instalment", "19"), TXT("owed", "Bills due before then", "rent 550 on the 1st")],
    "Only {left} left with {days} days to go and bills due: {owed}. Sections: steps in priority order for the next 48 hours (talk to accommodation office or landlord about a later rent date, university hardship fund, arranged-overdraft rules, food bank or community pantry, selling or pausing subscriptions); a checklist of what to gather for a hardship-fund application; a quote with an email to the university hardship or student-money team explaining the situation in under 120 words; a callout listing what NOT to do (payday loans, stacking buy-now-pay-later, ignoring rent) and reminding that student support services are confidential.", "steps, checklist, quote, callout", "Get me through", "Finding options…"),
  T("summer", "Summer gap plan", "No loan over the break", "☀️", [NUM("weeks", "Weeks of break", "14"), CH("plan", "This summer", ["Working full-time", "Paid internship", "Unpaid internship", "Living at home", "Staying in uni town"], "Working full-time"), NUM("costs", "Monthly costs over summer", "400")],
    "Summer: {weeks} weeks, plan: {plan}, monthly costs {costs}. Sections: kv (total summer cost, income needed, target savings to carry into next term, weekly allowance); table (Month | Income | Rent/costs | Save toward term | Notes); bullets on summer-only costs students forget (rent on an empty room, storage, travel home, local-tax rules for students); a callout on whether a summer sublet or a shorter contract makes sense for the profile.", "kv, table, bullets, callout", "Plan summer", "Planning summer…")], FIN)

# ---------------------------------------------------------------- couples: merging
APP("joint_jar", "Joint Jar", "Merge money with your partner without merging fights", "Finance", ["#AD1457", "#00897B", "#FFB74D"], "ring",
 "Joint Jar helps couples decide what's yours, mine and ours, split shared bills fairly when incomes differ, run a monthly money date, work through spending disagreements, and save for the goals you share.",
 "You are a calm couples money coach: fairness over equality, no scorekeeping, and you always give both partners a script.",
 "Two people, one plan", "A little about how you live and earn; nothing is shared with anyone.", ["Yours / mine / ours, designed for you", "Fair splits when incomes differ", "Money dates with an agenda"],
 [NAME, TXT("partner", "Partner's name", "Sam"), CH("stage", "Stage", ["Just moved in", "Living together a while", "Engaged", "Married", "Kids at home"]), CH("split", "Currently", ["Everything separate", "50/50 shared bills", "Proportional split", "One joint pot", "Not decided"])],
 [T("system", "Design our system", "Yours, mine, ours", "🏺", [NUM("income1", "Your monthly take-home", "2600"), NUM("income2", "Partner's monthly take-home", "1900"), NUM("shared", "Shared bills per month", "1850")],
    "Design a money system for the profile couple: you take home {income1}, your partner {income2}, shared bills are {shared}. Sections: cards for 3 systems (proportional split, one joint pot with equal personal allowances, 50/50 with a top-up from the higher earner), meta = fairness · simplicity · independence; table (Item | Who pays | From which account) for a typical month covering rent, groceries, subscriptions, debt, fun money; kv for the recommended system (each person's contribution, each person's personal money, joint buffer target); a callout on when to revisit the system (income change, baby, one partner studying or unemployed).", "cards, table, kv, callout", "Design it", "Balancing…"),
  T("fairsplit", "Fair split for a cost", "When incomes differ", "⚖️", [TXT("bill", "The cost", "holiday to Portugal 1400", True), CH("method", "Split by", ["Proportional to income", "Equal", "Whoever wanted it more", "Suggest one"], "Suggest one")],
    "Split {bill} using '{method}' for the profile couple. Sections: table (Method | Your share | Partner's share | Feels fair when…) comparing proportional, equal and a suggested hybrid; text recommending one for this specific cost and why; a quote with how to propose it to your partner in two sentences.", "table, text, quote", "Split it", "Weighing…"),
  T("date", "Monthly money date", "A 30-minute agenda", "🗓️", [TXT("month", "What happened this month", "overspent on eating out, car needs tyres"), CH("mood", "Mood going in", ["Fine", "Tense", "Avoiding it"], "Fine")],
    "Run a 30-minute money date; this month: {month}; mood: {mood}. Sections: steps with minutes for each agenda item (wins first, the numbers, upcoming costs, one decision, book the next date); kv (3 numbers to look at together); bullets of ground rules (no blame words, phones down, one topic parked if heated); a quote with an opening line that lowers the temperature.", "steps, kv, bullets, quote", "Set the agenda", "Lighting candles…"),
  T("clash", "We disagree about money", "Spender vs saver, and the rest", "🌧️", [LONG("issue", "What the disagreement is", "I think 300/month on takeaways is fine, they think it's reckless")],
    "Help the profile couple with: {issue}. Sections: text naming the pattern underneath (values, fear, childhood money scripts) without taking sides; table (Your view | Partner's view | What each is protecting); steps for a 20-minute conversation that ends in a one-month experiment; a quote with a sentence each partner could say to open; a callout on signs the issue is financial control rather than disagreement, and where to seek confidential support.", "text, table, steps, quote, callout", "Help us talk", "Listening…"),
  T("goal", "Save for a shared goal", "Deposit, wedding, trip, baby", "🎯", [TXT("goal", "The goal", "house deposit 30,000", True), TXT("by", "Target date", "in 3 years"), NUM("saved", "Already saved", "6000")],
    "Shared goal {goal} by {by}, already saved {saved}. Sections: kv (amount still needed, monthly total, a fair monthly split for each partner based on the profile's current arrangement, expected date at that pace); table (Milestone | Amount | Month) with 5 checkpoints; bullets of 4 ways to shorten it; a callout on keeping goal money separate from the emergency buffer and being clear whose name the account is in.", "kv, table, bullets, callout", "Plan the goal", "Saving up…")], FIN)

# ---------------------------------------------------------------- couples: separating
APP("untangle_money", "Untangle", "Separate your money after a breakup, fairly and fast", "Finance", ["#455A64", "#EF6C00", "#7E57C2"], "scale",
 "Untangle helps couples who are splitting up divide shared money calmly: who keeps what, closing joint accounts and subscriptions, settling the deposit and the furniture, rebuilding a solo budget, and the messages that get you paid back.",
 "You are a practical, neutral separation money guide: you keep score only where it matters, protect both people from rash moves, and know when a lawyer or mediator is worth the fee.",
 "Split the money, keep your head", "A few facts about the situation keep the advice relevant.", ["A fair division of shared things", "Joint accounts and bills, closed cleanly", "Scripts for the awkward messages"],
 [NAME, CH("status", "Legal status", ["Unmarried, living together", "Married / civil partnership", "Engaged", "Not sure"]), CH("home", "Home", ["Renting together", "One of us owns it", "Own together", "Neither / other"]), TXT("country", "Country / region", "UK")],
 [T("inventory", "Divide what's shared", "Furniture, deposit, pets, debt", "📦", [LONG("items", "Shared things & money", "sofa 900 (I paid), deposit 1500 (split), joint credit card 1200 owed, the dog…"), CH("style", "You want to be", ["Strictly fair", "Generous to move on", "Firm, they've been unfair"], "Strictly fair")],
    "Shared items and money: {items}; approach: {style}. Sections: table (Item | Who paid / whose name | Suggested outcome | Reasoning); kv (net balancing payment and who pays whom); a callout on items that are legally different from 'stuff' (joint debt, tenancy deposits, pets, anything in one name only) and which need advice given the profile's status and region; a quote with a short neutral message proposing the split.", "table, kv, callout, quote", "Propose a split", "Untangling…"),
  T("accounts", "Close the joint stuff", "Accounts, bills, subscriptions", "✂️", [LONG("joint", "Everything joint", "joint current account, Netflix on my card, energy in both names, phone family plan…")],
    "Joint items: {joint}. Sections: checklist in the safest order (freeze new borrowing first, then bills, then subscriptions, then close accounts), one line per item with who does it; table (Item | Risk if left open | Action | Deadline); a callout on protecting your credit file from a joint account or shared address and on never emptying a joint account unilaterally; steps for the day you close the main joint account.", "checklist, table, callout, steps", "Make the list", "Cutting cords…"),
  T("housing", "Who stays, who goes", "Rent, deposit and moving costs", "🏠", [NUM("rent", "Monthly rent / mortgage", "1400"), NUM("deposit", "Deposit held", "1600"), CH("plan", "Likely outcome", ["I stay", "They stay", "Both leave", "Undecided"], "Undecided")],
    "Home cost {rent}, deposit {deposit}, likely outcome {plan}, home situation from the profile. Sections: table (Option | Monthly cost to you | Deposit handling | Notice / moving cost | Watch-outs) comparing you staying, them staying and both leaving; kv (cash you need to leave, or to stay alone, including first month and deposit); a callout on tenancy or ownership rules that vary by region (notice, release from a joint tenancy, landlord consent, who is liable) and that this is not legal advice; a quote with a message to the landlord or agent asking what is possible.", "table, kv, callout, quote", "Compare options", "Measuring rooms…"),
  T("solo", "My solo budget", "Life on one income again", "🧍", [NUM("income", "Your monthly take-home", "2300"), LONG("costs", "Your new costs", "rent 950, transport 90, phone 20, groceries 250…")],
    "Rebuild a single budget: income {income}, costs {costs}. Sections: table (Category | Amount | Share of income | Adjust?); kv (left over per month, emergency-fund target for a solo household, weeks to reach it); bullets of 5 costs that quietly doubled after the split and how to soften each; a callout on the first 3 months being the expensive ones and what to tell yourself about it.", "table, kv, bullets, callout", "Rebuild", "Resetting…"),
  T("message", "Write the money message", "Ask for what you're owed, calmly", "✉️", [LONG("situation", "What you need to say", "they owe me 400 for the last month's bills and haven't replied in 2 weeks"), CH("tone", "Tone", ["Warm", "Neutral", "Firm", "Final notice"], "Neutral")],
    "Draft a message about: {situation}, tone {tone}. Sections: quote with the message (under 120 words, one clear ask, a date, no raking over history); bullets on what to do if there is no reply (keep a written record, mediation or small-claims as general options, when to let it go); a callout on keeping evidence (screenshots, bank records) and avoiding anything that reads as a threat.", "quote, bullets, callout", "Write it", "Choosing words…")], SEP)

